# Double-click interaction for the first row in the QCL worklist grid.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def double_click_first_row() -> bool:
    rows = CommonActions.get_all_objects_by_map(MosaiqQCLObjects.QCL_Row)
    if not rows:
        raise RuntimeError("No rows were found in the QCL worklist grid")

    cells = CommonActions.get_child_objects(rows[0])
    if not cells:
        raise RuntimeError("The first QCL row has no cells to double-click")

    CommonActions.double_click_object(cells[0])
    time.sleep(0.3)
    return True

# Helper functions for reading values from QCL grid objects and their descendants.
def _get_object_value(obj) -> str:
    if obj is None:
        return ""

    for attribute_name in ("value", "text", "displayText", "caption"):
        try:
            value = getattr(obj, attribute_name, None)
            if value is not None:
                value_str = str(value).strip()
                if value_str:
                    return value_str
        except Exception:
            continue

    try:
        children = CommonActions.get_child_objects(obj)
        for child in children:
            child_value = _get_object_value(child)
            if child_value:
                return child_value
    except Exception:
        pass

    try:
        name_value = str(getattr(obj, "name", "") or "").strip()
        if name_value and not re.match(r"^(tb|popupcontaineredit|layout|lci|edit|windowsforms|.*_.*)$", name_value, re.IGNORECASE):
            return name_value
    except Exception:
        pass

    return ""

# Helper function for safely reading an optional attribute from a Squish object.
def _get_object_attribute(obj, attribute_name: str) -> str:
    """Read an optional Squish accessibility attribute without raising."""
    try:
        value = getattr(obj, attribute_name, "")
        return str(value).strip() if value is not None else ""
    except Exception:
        return ""
