# Helper function for normalizing QCL description values.
def _normalize_description(value: str) -> str:
    """Remove display-only quote characters from a QCL description."""
    return str(value).strip().strip('"')

# QCL worklist reading functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_qcl_entries() -> list[str]:
    rows = CommonActions.get_all_objects_by_map(MosaiqQCLObjects.QCL_Row)
    print(f"Found {len(rows)} QCL rows")

    entries = []
    for row in rows:
        try:
            cells = CommonActions.get_child_objects(row)
        except Exception:
            continue
        if not cells:
            continue
        # The Description column is the first cell in each row.
        description = _get_object_value(cells[0])
        if description:
            entries.append(description)
    return entries

# QCL task and department reading functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_qcl_task_and_department() -> list[tuple[str, str]]:
    rows = CommonActions.get_all_objects_by_map(MosaiqQCLObjects.QCL_Row)
    print(f"Found {len(rows)} QCL rows")

    entries = []
    for row in rows:
        try:
            cells = CommonActions.get_child_objects(row)
        except Exception:
            continue

        task_name = ""
        department = ""
        for cell in cells:
            cell_name = _get_object_attribute(cell, "name").casefold()
            if cell_name.startswith("description row"):
                task_name = _get_object_value(cell)
            elif cell_name.startswith("department row"):
                department = _get_object_value(cell)

        if task_name:
            entries.append((task_name, department))
    return entries


_ROW_SUFFIX_PATTERN = re.compile(r"\s*row\s*\d+\s*$", re.IGNORECASE)

# Read and print individual QCL row data functions
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_qcl_row_data(row_index: int = 0) -> dict:
    rows = CommonActions.get_all_objects_by_map(MosaiqQCLObjects.QCL_Row)
    if row_index < 0 or row_index >= len(rows):
        raise IndexError(f"Row index {row_index} is out of range for {len(rows)} QCL rows")

    try:
        cells = CommonActions.get_child_objects(rows[row_index])
    except Exception:
        cells = []

    row_data = {}
    for cell in cells:
        cell_name = _get_object_attribute(cell, "name")
        header = _ROW_SUFFIX_PATTERN.sub("", cell_name).strip()
        if header:
            row_data[header] = _get_object_value(cell)
    return row_data

# QCL row printing functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def print_qcl_row(row_index: int = 0) -> dict:
    row_data = read_qcl_row_data(row_index)
    print(f"QCL row {row_index} data:")
    for header, value in row_data.items():
        print(f"  {header}: {value!r}")
    return row_data

# QCL popup field reading and comparison functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_qcl_popup_fields() -> dict:
    popup = None
    for candidate in (
        {"text": objectmaphelper.Wildcard("Quality Check List Task*"), "type": "Window"},
        {"text": objectmaphelper.Wildcard("Quality Check List Task*"), "type": "Dialog"},
    ):
        try:
            matches = CommonActions.get_all_objects_by_map(candidate)
        except Exception:
            matches = ()
        if matches:
            popup = matches[0]
            break

    data = {}
    if popup is not None:
        for field_name, field_locator in {
            "Description": MosaiqQCLObjects.Description_Value_detail,
            
        }.items():
            try:
                field_obj = CommonActions.find_object(field_locator)
                data[field_name] = _get_object_value(field_obj)
                if field_name == "Description":
                    data[field_name] = _normalize_description(data[field_name])
            except Exception:
                data[field_name] = ""
        '''
        try:
            inactive_obj = CommonActions.find_object(MosaiqQCLObjects.Inactive_CheckBox_detail)
            data["InactiveEnabled"] = bool(getattr(inactive_obj, "enabled", False))
            data["Inactive"] = _read_checkbox_state(inactive_obj)
        except Exception:
            data["InactiveEnabled"] = None
            data["Inactive"] = None
            '''

    print(f"QCL popup fields after double-click: {data}")
    return data

# QCL row comparison functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def compare_first_qcl_row_after_double_click() -> dict:
    before_row = read_qcl_row_data(0)
    if not before_row:
        raise RuntimeError("No data found in the first QCL row")

    before_compare = {
        "Description": _normalize_description(before_row.get("Description", "")),
    }
    print(f"QCL values before double-click: {before_compare}")

    double_click_first_row()
    time.sleep(0.5)
    popup_fields = read_qcl_popup_fields()

    print(f"QCL values after double-click: {popup_fields}")

    if before_compare["Description"] != popup_fields.get("Description", ""):
        raise AssertionError(
            f"Description changed after double-click: before={before_compare['Description']!r}, "
            f"after={popup_fields.get('Description', '')!r}"
        )

    return {"before": before_compare, "after": popup_fields}


# QCL header reading functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_qcl_headers() -> list[str]:
    header_panel_matches = CommonActions.get_all_objects_by_map(MosaiqQCLObjects.QCL_Header_Panel)
    if not header_panel_matches:
        return []

    try:
        header_cells = CommonActions.get_child_objects(header_panel_matches[0])
    except Exception:
        return []

    headers = []
    for cell in header_cells:
        header_text = _get_object_value(cell)
        if header_text:
            headers.append(header_text)
    return headers

# QCL row reading functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def print_qcl_row_with_headers(row_index: int = 0) -> dict:
    headers = read_qcl_headers()
    row_data = read_qcl_row_data(row_index)
    print(f"QCL headers: {headers}")

    matched = {}
    for header in headers:
        value = next(
            (row_data[key] for key in row_data if key.casefold() == header.casefold()),
            "",
        )
        matched[header] = value

    print(f"QCL row {row_index} (header: value):")
    for header, value in matched.items():
        print(f"  {header}: {value!r}")
    return matched


# Kept as a fallback only - Object Spy confirmed the QCL grid uses DevExpress accessibility
# objects (read via read_qcl_entries()), not an owner-drawn ClaList control like Orders.
_LB_GETCOUNT = 0x018B
_LB_GETTEXT = 0x0189
_LB_GETTEXTLEN = 0x018A

# Fallback functions for reading QCL rows via native Win32 ListBox messages.
def _read_listbox_rows_via_hwnd(hwnd: int) -> list[str]:
    """Best-effort read of a native control's rows via raw Win32 ListBox messages."""
    if not hwnd:
        return []

    user32 = ctypes.windll.user32
    try:
        row_count = user32.SendMessageW(hwnd, _LB_GETCOUNT, 0, 0)
    except Exception:
        return []

    if row_count <= 0:
        return []

    rows = []
    for index in range(row_count):
        try:
            text_len = user32.SendMessageW(hwnd, _LB_GETTEXTLEN, index, 0)
            if text_len <= 0:
                continue
            buffer = ctypes.create_unicode_buffer(text_len + 1)
            user32.SendMessageW(hwnd, _LB_GETTEXT, index, ctypes.byref(buffer))
            if buffer.value:
                rows.append(buffer.value)
        except Exception:
            continue
    return rows

# QCL native grid reading functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_qcl_entries_via_native_grid() -> list[str]:
    native_controls = CommonActions.get_all_objects_by_map(MosaiqQCLObjects.QCL_Native_Grid_Controls)
    print(f"Found {len(native_controls)} native QCL grid control(s)")

    for control in native_controls:
        hwnd = getattr(control, "hwnd", None)
        print(f"  control hwnd={hwnd!r}")
        rows = _read_listbox_rows_via_hwnd(hwnd)
        print(f"    rows read via LB_GETTEXT: {rows}")
        if rows:
            return rows

    return []
