# QCL entry verification functions.
@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def verify_qcl_has_entries() -> bool:
    task_and_department = read_qcl_task_and_department()
    if task_and_department:
        print(f"QCL entries (task, department) found: {task_and_department}")
        return True

    entries = read_qcl_entries_via_native_grid()
    print(f"QCL entries found: {entries}")
    if not entries:
        raise AssertionError("Expected at least one entry in the QCL worklist grid, but none were found")
    return True
